170: export function describeSnapshot(snapshot) {
171:   const stage = snapshot.stage ?? 1;
172:   const latencyMs = Math.round(snapshot.avgLatencyTicks * TICK_MS);
173:   const last = snapshot.lastExchange ?? null;
174:   const hop = snapshot.trace?.hop ?? 0;
175:   const serverAddress = snapshot.serverAddress ?? '10.1';
176:   const s1Depth = snapshot.servers?.[0]?.queueDepth ?? snapshot.queueDepth;
177:   const s2Depth = snapshot.servers?.[1]?.queueDepth ?? 0;
178:   const perBackend = snapshot.loadBalancer?.perBackend ?? {};
179:   // CHECKS: per-tick throughput is served/tick while the clock runs and
180:   // exactly 0 at tick 0 — the SERVED card renders "0.00/t", never NaN or
181:   // Infinity (named counter-example: a fresh Stage-1 panel at tick 0).
182:   const servedPerTick = snapshot.tick > 0 ? (snapshot.served ?? 0) / snapshot.tick : 0;
183:   return {
184:     stage,
185:     totalHops: TOTAL_HOPS[stage] ?? 4,
186:     tick: String(snapshot.tick),
187:     users: String(snapshot.users),
188:     queueDepth: String(snapshot.queueDepth),
189:     served: String(snapshot.served),
190:     servedRate: `${servedPerTick.toFixed(2)}/t`,
191:     latency: `${latencyMs} ms`,
192:     queueFill: fillPercent(snapshot.queueDepth),
193:     queueFill1: fillPercent(s1Depth),
194:     queueFill2: fillPercent(s2Depth),
195:     serverAddress,
196:     server1Address: snapshot.servers?.[0]?.address ?? serverAddress,
197:     server2Address: snapshot.servers?.[1]?.address ?? '10.12',
198:     lbNextBackend: snapshot.loadBalancer
199:       ? `Next -> ${snapshot.loadBalancer.nextBackend}`
200:       : 'Next -> 10.11',
201:     lbBackend1Label: `10.11 WebServer-1 (${perBackend['10.11'] ?? 0})`,
202:     lbBackend2Label: `10.12 WebServer-2 (${perBackend['10.12'] ?? 0})`,
203:     cacheStatsLabel: `Hits: ${snapshot.cache?.hits ?? 0} · Misses: ${snapshot.cache?.misses ?? 0} · TTL: ${snapshot.cache?.ttlTicks ?? 10}t`,
204:     cacheEntries: snapshot.cache?.entries ?? [],
205:     dbStatsLabel: `Reads: ${snapshot.database?.reads ?? 0} · Writes: ${snapshot.database?.writes ?? 0} · Lag: ${snapshot.database?.replicationLagTicks ?? 3}t`,
206:     dbRows: snapshot.database?.rows ?? [],
207:     queueStatsLabel: snapshot.workerQueue
208:       ? `Enqueued: ${snapshot.workerQueue.enqueued} · Completed: ${snapshot.workerQueue.completed} · Active: ${
209:           snapshot.workerQueue.activeJob
210:             ? `#${snapshot.workerQueue.activeJob.jobId} ${snapshot.workerQueue.activeJob.path}`
211:             : 'none'
212:         }`
213:       : 'Enqueued: 0 · Completed: 0 · Active: none',
214:     workerStatsLabel: snapshot.workerQueue
215:       ? snapshot.workerQueue.activeJob
216:         ? `Worker ${snapshot.workerQueue.workerAddress} processing #${snapshot.workerQueue.activeJob.jobId} (${snapshot.workerQueue.activeJob.path})`
217:         : `Worker ${snapshot.workerQueue.workerAddress} Idle`
218:       : 'Worker 10.41 Idle',
219:     queueJobs: snapshot.workerQueue?.pendingJobs ?? [],
220:     dnsStatsLabel: `Lookups: ${snapshot.dns?.lookups ?? 0} · Cached: ${
221:       snapshot.dns?.cachedHits ?? 0
222:     } · Authoritative: ${snapshot.dns?.authoritative ?? 0} · TTL: ${snapshot.dns?.ttlTicks ?? 300}t`,
223:     // PINS: the DNS ledger renders one row per live cache entry — name,
224:     // resolved target, ticks left — the Map on screen, not an aggregate.
225:     dnsEntries: snapshot.dns?.cache ?? [],
226:     // CHECKS (Stage 6b): the edge HUD mirrors the fill ledger's counters and
227:     // TTL from the live snapshot — hits/misses/fills are the edge's own
228:     // lookup tally, and rows carry the per-entry remaining ticks.
229:     cdnStatsLabel: `Hits: ${snapshot.cdn?.hits ?? 0} · Misses: ${snapshot.cdn?.misses ?? 0} · Fills: ${
230:       snapshot.cdn?.fills ?? 0
231:     } · TTL: ${snapshot.cdn?.ttlTicks ?? 10}t`,
232:     cdnEntries: snapshot.cdn?.ledger ?? [],
233:     routerStatsLabel: snapshot.router
234:       ? `Router ${snapshot.router.address} ⇄ ${snapshot.router.rightAddress} · Routed: ${snapshot.router.routed}`
235:       : '',
236:     exchangeSummary: last
237:       ? `${last.from} -> ${last.to} ${last.request} => ${last.response}`
238:       : 'No requests served yet',
239:     hop,
240:     hopStatus: formatHopStatus(snapshot, serverAddress),
241:     browserStatus: snapshot.browserDisplay
242:       ? `${snapshot.browserDisplay.status} (${snapshot.browserDisplay.request})`
243:       : 'No response yet',
244:     browserBody: snapshot.browserDisplay
245:       ? snapshot.browserDisplay.body
246:       : 'Send a request or step a hop to render a response.',
247:     networkLastFrame: snapshot.lastFrame ?? 'No frames routed yet',
248:     matchedRouteId: snapshot.lastMatchedRoute ?? null,
249:   };
250: }

