2: // trace-stage6.js by responsibility (guard-file-size): the stage-6 machine
3: // stays the DNS/ask-answer prelude plus the byte-identical stage-5 chain,
4: // and this module owns the chain whose DNS answer lives in the edge's
5: // subnet. The engine hands in the real components (cdn.js edge, router.js,
6: // loadbalancer, backend servers) with itself as no shortcut: hop 3 and hop
7: // 5/8 are real `router.forward` crossings (`routed` +1 per crossing), the
8: // MISS pull's left-network delivery IS the real `lb.enqueue`, hop 7 really
9: // drains the origin backend so its cache-aside status rides the frame, and
10: // hop 8 fills the edge ledger only with the bytes that pull really
11: // returned. HIT = 6 hops, MISS and non-GET pass-through = 9.
12: //
13: // CHECKS: (negative cases pinned in test/sim/cdn.test.js and
14: // test/sim/engine.test.js) a miss or expired entry answers only from a
15: // fresh pull — the ledger answers nothing outside its tick window — and a
16: // non-GET leaves the ledger untouched (no lookup, no counters, no row; the
17: // machine's hop 4 marks PASS and the fill branch only runs on a MISS); a
18: // GET inside the edge TTL is served from ledger bytes `fill` recorded
19: // earlier — nothing fabricated.
20: export function createCdnChain({
21:   cdn,
22:   router,
23:   lb,
24:   servers,
25:   bumpTick,
26:   getTick,
27:   onServe,
28:   onFinish,
29:   getTrace,
30: }) {
31:   if (!cdn || !router || !lb) {
32:     throw new Error('cdn-chain: cdn, router, and lb are required');
33:   }
34: 
35:   // The machine's live trace object (recreated per hop-1 emission); this
36:   // chain reads and writes it in place, one hop per call.
37:   const trace = () => getTrace();
38: 
39:   function drainUntilYou(targetServer) {
40:     for (;;) {
41:       const batch = targetServer.step(getTick());
42:       const you = batch.find((item) => item.isYou);
43:       if (you || batch.length === 0) return you;
44:     }
45:   }
46: 
47:   function backendFor(targetAddress) {
48:     return servers.find((s) => s.address === targetAddress) ?? servers[0];
49:   }
50: 
51:   function serve(you) {
52:     const t = trace();
53:     t.response = you.response;
54:     t.status = you.status;
55:     t.body = you.body;
56:     t.routeId = you.routeId;
57:     t.cacheStatus = you.cacheStatus ?? null;
58:     t.dbOp = you.dbOp ?? null;
59:     t.dbStale = Boolean(you.dbStale);
60:     t.asyncJob = Boolean(you.asyncJob);
61:     onServe(you);
62:   }
63: 
64:   function finish(toAddress) {
65:     const t = trace();
66:     onFinish({
67:       from: t.from ?? '10.2',
68:       to: toAddress,
69:       request: t.request,
70:       response: t.response,
71:     });
72:   }
73: 
74:   // The response crosses BACK through the Router into the originating
75:   // browser's left-network seat (`routed` +1, each direction counts). The
76:   // frame's wire token is the slim response record ("<status> <body>") —
77:   // one token per frame on this wire, whatever kind crosses it; the browser
78:   // seat acknowledges the frame and the render hop performs the real
79:   // onFinish delivery.
80:   function deliverResponse(note = '') {
81:     const t = trace();
82:     router.forward({
83:       id: `edge-resp:${getTick()}`,
84:       from: cdn.address,
85:       to: t.from,
86:       request: t.response,
87:       atTick: getTick(),
88:       isYou: true,
89:     });
90:     return `${router.address} -> ${t.from} | ${t.response} delivered${note}`;
91:   }
