93:   // One hop per call; `hop` mirrors the stage-6 machine's is a real step
94:   // number (3-9) and the trace advances exactly one hop per call either
95:   // way. Frames consume the components' actual messages — the Router's
96:   // crossings, the ledger rows, the LB's real pick, the drained origin
97:   // record — per the cdn.js and router.js contracts.
98:   function step(hop) {
99:     const t = trace();
100:     t.hop = hop;
101:     if (hop === 3) {
102:       // One explicit tick per trace run (the stage-5 chain bumps at its
103:       // enqueue hop — same determinism contract, one bump per run).
104:       bumpTick();
105:       router.forward({
106:         id: `you:${getTick()}`,
107:         from: t.from,
108:         to: cdn.address,
109:         request: t.request,
110:         atTick: getTick(),
111:         isYou: true,
112:       });
113:       return `${t.from} -> ${router.address} | ${t.request} (to ${cdn.address})`;
114:     }
115:     if (hop === 4) {
116:       if (t.method !== 'GET') {
117:         // GET-only edge: a non-GET leaves the ledger untouched (the pull
118:         // still goes to the origin — the MISS shape minus the fill).
119:         t.edgeStatus = 'PASS';
120:         return `${cdn.address} -> ${router.address} | PASS — ${t.method} ${t.path} is not edge-cacheable, pulling origin ${cdn.originAddress} via router`;
121:       }
122:       const result = cdn.lookup(t.path, getTick());
123:       t.edgeStatus = result.status;
124:       if (result.status === 'MISS') {
125:         return `${cdn.address} -> ${router.address} | MISS — pulling origin ${cdn.originAddress} via router`;
126:       }
127:       // HIT: the ledger row's own bytes (filled by an earlier real pull)
128:       // are what leaves the edge — ttl is the row's remaining ticks.
129:       const entry = cdn.snapshot(getTick()).ledger.find((row) => row.path === t.path);
130:       t.response = `200 ${entry.body}`;
131:       t.status = 200;
