136:         from: cdn.address,
137:         to: t.from,
138:         request: t.request,
139:         isYou: true,
140:         response: t.response,
141:         status: t.status,
142:         body: t.body,
143:         routeId: t.routeId,
144:         cacheStatus: 'HIT',
145:       });
146:       return `${cdn.address} -> ${router.address} | ${t.response} (edge HIT, ttl ${entry.ttlRemaining}t)`;
147:     }
148:     if (hop === 5) {
149:       if (t.edgeStatus === 'HIT') {
150:         return deliverResponse();
151:       }
152:       // The edge really pulls the origin through the Router: the crossing
153:       // is `routed` +1 and the delivered frame IS the real lb.enqueue — the
154:       // narrated queueing is the round-robin pick that really happened.
155:       router.forward({
156:         id: `edge-pull:${getTick()}`,
157:         from: cdn.address,
158:         to: cdn.originAddress,
159:         request: t.request,
160:         atTick: getTick(),
161:         isYou: true,
162:       });
163:       t.targetServer = lb.snapshot().lastTarget;
164:       return `${cdn.address} -> ${cdn.originAddress} | ${t.request} (edge pull via router)`;
165:     }
166:     if (hop === 6) {
167:       if (t.edgeStatus === 'HIT') {
168:         finish(cdn.address);
169:         return `Browser ${t.from} received and displayed ${t.status}`;
170:       }
171:       return `LB ${cdn.originAddress} -> ${t.targetServer} (${t.request}) queued`;
172:     }
173:     if (hop === 7) {
174:       const backend = backendFor(t.targetServer);
175:       const served = drainUntilYou(backend);
176:       if (!served) return null;
177:       serve(served);
178:       return `${backend.address} -> ${router.address} | ${served.response} (cache ${served.cacheStatus})`;
179:     }
180:     if (hop === 8) {
181:       if (t.edgeStatus === 'MISS') {
182:         // The pulled origin bytes are exactly what enters the ledger — the
183:         // fill is the chain's only ledger write, after a real pull.
184:         cdn.fill(t.path, t.body, getTick());
185:         return deliverResponse(` (edge FILL ${t.path}, ttl ${cdn.ttlTicks}t)`);
186:       }
187:       return deliverResponse(' (no edge FILL — non-GET pass-through)');
188:     }
189:     if (hop === 9) {
190:       finish(t.targetServer ?? cdn.originAddress);
191:       return `Browser ${t.from} received and displayed ${t.status}`;
192:     }
193:     return null;
194:   }
195: 
196:   return { step };
197: }

