// PINS: slot allocation over the two most recent completed trace runs —
// the trace-runs-only counter-example is enforced here: a run with fewer
// than 2 hops or no hop entries (a crowd tick, shaped { hops: 0 }) is
// ignored, and a push whose run id already sits in a slot is a no-op
// (changed: false, slots untouched). First distinct run fills A, the
// second fills B (changed: true), a third shifts A <- old B, B <- new.
export function nextCompareSlots(slots, newRun) {
  if (
    !newRun ||
    !Array.isArray(newRun.entries) ||
    newRun.entries.length === 0 ||
    (newRun.hops ?? 0) < 2
  ) {
    return { a: slots.a ?? null, b: slots.b ?? null, changed: false };
  }
  if (slots.a?.run === newRun.run || slots.b?.run === newRun.run) {
    return { a: slots.a, b: slots.b, changed: false };
  }
  if (!slots.a) return { a: newRun, b: slots.b ?? null, changed: true };
  if (!slots.b) return { a: slots.a, b: newRun, changed: true };
  return { a: slots.b, b: newRun, changed: true };
}
