// Pure insertion into a sorted journey list (no DOM here): returns the
// ordered array with the new entry placed so the run key order holds.
export function orderJourneyEntries(entries, entry) {
  const ordered = [...entries];
  const index = ordered.findIndex((existing) => journeyEntryIsBefore(entry, existing));
  if (index === -1) ordered.push(entry);
  else ordered.splice(index, 0, entry);
  return ordered;
}

// PINS: the compare tray's rows align by hop index over the taller run,
// and the exhausted side renders an em-dash. Entry texts pass through
// byte-identically — the tray never mints, rewrites, or summarizes hop
// frames (AGENTS.md DL-1; verbatim journey-log entries only). Named
// counter-example: 9-by-6 runs give 9 rows with rows 7-9 reading '—' on
// the right; nothing drops (pinned in test/panel/model.test.js).
export function alignCompareRows(left, right) {
  const total = Math.max(left.hops, right.hops);
  const rows = [];
  for (let n = 1; n <= total; n += 1) {
    rows.push({
      n,
      left: left.entries.find((entry) => entry.hop === n)?.text ?? '—',
      right: right.entries.find((entry) => entry.hop === n)?.text ?? '—',
    });
  }
  return rows;
}

// PINS: slot allocation for the two most recent completed trace runs.
// Rejection rule spelled out: a run with fewer than 2 hops or with no hop
// entries is ignored — that is the trace-runs-only counter-example's
// machine form (a crowd tick, shaped `{ hops: 0 }`, never shifts slots).
// A run whose id already sits in a slot is a no-op (the tray does not
// duplicate); otherwise the first distinct run fills A, the second fills
// B, and a third shifts A <- old B, B <- new. Pure: slots and the stored
// run objects are never mutated (snapshot-at-completion immunity).
export function nextCompareSlots(slots, newRun) {
  const complete =
    newRun && Array.isArray(newRun.entries) && newRun.entries.length > 0 && (newRun.hops ?? 0) >= 2;
  if (!complete || slots.a?.run === newRun.run || slots.b?.run === newRun.run) {
    return { a: slots.a ?? null, b: slots.b ?? null, changed: false };
  }
  if (!slots.a) return { a: newRun, b: slots.b ?? null, changed: true };
  if (!slots.b) return { a: slots.a, b: newRun, changed: true };
  return { a: slots.b, b: newRun, changed: true };
}

