  grid-template-columns: 1.5rem minmax(0, 1fr) minmax(0, 1fr);
  gap: 0.6rem;
  align-items: baseline;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-size: 0.78rem;
}

.compare-n {
  color: var(--text-muted);
  text-align: right;
}

.compare-cell {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

